import{_ as e,c as r,o as a,ag as n}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"Alerts and Notifications","description":"Configuring alert triggers and actions","frontmatter":{"title":"Alerts and Notifications","description":"Configuring alert triggers and actions"},"headers":[],"relativePath":"engine/alerts_and_notifications.md","filePath":"engine/alerts_and_notifications.md","lastUpdated":1788476353000}'),o={name:"engine/alerts_and_notifications.md"};function s(d,t,i,l,c,h){return a(),r("div",null,t[0]||(t[0]=[n('<h1 id="alerts-and-notifications" tabindex="-1">Alerts and Notifications <a class="header-anchor" href="#alerts-and-notifications" aria-label="Permalink to &quot;Alerts and Notifications&quot;">​</a></h1><p>OIE includes a built-in, error-driven alerting system that watches for problems on selected channels and takes action when they occur, typically sending an email or routing data to another channel.</p><h2 id="how-alerts-work" tabindex="-1">How alerts work <a class="header-anchor" href="#how-alerts-work" aria-label="Permalink to &quot;How alerts work&quot;">​</a></h2><p>An alert is a background process that watches for specific categories of errors on the channels and connectors you choose. When a matching error occurs, the alert fires all of its configured actions, sending emails, notifying users, or dispatching a message to a designated channel.</p><p>The <strong>Alerts</strong> view in the main navigation shows a summary table of all configured alerts:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Whether the alert is currently enabled or disabled</td></tr><tr><td><strong>Name</strong></td><td>The alert name</td></tr><tr><td><strong>Id</strong></td><td>The alert&#39;s unique identifier</td></tr><tr><td><strong>Alerted</strong></td><td>How many times the alert has fired since it was last enabled</td></tr></tbody></table><h2 id="creating-and-editing-an-alert" tabindex="-1">Creating and editing an alert <a class="header-anchor" href="#creating-and-editing-an-alert" aria-label="Permalink to &quot;Creating and editing an alert&quot;">​</a></h2><p>Click <strong>New Alert</strong> in the Alerts task panel, or select an existing alert and click <strong>Edit Alert</strong> (you can also double-click an alert row). The Edit Alert view has three main configuration areas: error types, channel selection, and actions.</p><h3 id="error-types-and-regex" tabindex="-1">Error types and regex <a class="header-anchor" href="#error-types-and-regex" aria-label="Permalink to &quot;Error types and regex&quot;">​</a></h3><p>Choose which categories of error should trigger the alert. You can select one or more from the following list:</p><table tabindex="0"><thead><tr><th>Error Category</th><th>What It Covers</th></tr></thead><tbody><tr><td><strong>Any</strong></td><td>All error categories at once</td></tr><tr><td><strong>Source Connector</strong></td><td>Errors during source connector startup, message receipt, or response delivery</td></tr><tr><td><strong>Destination Connector</strong></td><td>Errors during destination connector startup, message dispatch, or response receipt</td></tr><tr><td><strong>Serializer</strong></td><td>Errors when converting a message to or from its internal representation (e.g. parsing HL7 to XML)</td></tr><tr><td><strong>Filter</strong></td><td>Errors thrown by a source or destination filter rule</td></tr><tr><td><strong>Transformer</strong></td><td>Errors thrown by a source or destination transformer step</td></tr><tr><td><strong>User Defined Transformer</strong></td><td>Errors dispatched by a manual call to <code>alerts.sendAlert(errorMessage)</code> from any script</td></tr><tr><td><strong>Response Validation</strong></td><td>Errors from destination response validation. For example, receiving an HL7 NACK</td></tr><tr><td><strong>Response Transformer</strong></td><td>Errors from a destination&#39;s response transformer step</td></tr><tr><td><strong>Attachment Handler</strong></td><td>Errors from the attachment handler</td></tr><tr><td><strong>Deploy Script</strong></td><td>Errors from a channel&#39;s deploy script</td></tr><tr><td><strong>Preprocessor Script</strong></td><td>Errors from a global or channel preprocessor script</td></tr><tr><td><strong>Postprocessor Script</strong></td><td>Errors from a global or channel postprocessor script</td></tr><tr><td><strong>Undeploy Script</strong></td><td>Errors from a channel&#39;s undeploy script</td></tr></tbody></table><p>You can optionally provide a <strong>regex pattern</strong> that is matched against the full error output, a composite string that includes the error type, error source line (if available), the custom error message, and the exception stack trace. Only errors whose combined output matches the regex will trigger the alert.</p><h3 id="channel-and-connector-selection" tabindex="-1">Channel and connector selection <a class="header-anchor" href="#channel-and-connector-selection" aria-label="Permalink to &quot;Channel and connector selection&quot;">​</a></h3><p>The channel tree lets you pick exactly which channels and connectors the alert should monitor. You can enable or disable individual connectors within a channel. For example, watching only the source connector and ignoring destinations.</p><p>Two special entries are available:</p><ul><li><strong>[New Channels]</strong>. Automatically include any channel created after the alert was set up</li><li><strong>[New Destinations]</strong>. Automatically include any new destination added to an already-monitored channel</li></ul><p>Use the <strong>Filter</strong> field above the tree to search channels by name, and the <strong>Enable</strong> / <strong>Disable</strong> buttons to toggle selection in bulk.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Each alert can have multiple actions that all fire when the alert triggers. For every action, you choose a <strong>protocol</strong> and a <strong>recipient</strong>:</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Email</strong></td><td>Sends an email to the address specified in the Recipient column. Uses the Subject and Template fields.</td></tr><tr><td><strong>User</strong></td><td>Sends an email to the email address on file for the selected OIE user account</td></tr><tr><td><strong>Channel</strong></td><td>Dispatches the Template content as a message to the channel specified in the Recipient column. The Subject field is ignored.</td></tr></tbody></table><h4 id="subject-and-template" tabindex="-1">Subject and template <a class="header-anchor" href="#subject-and-template" aria-label="Permalink to &quot;Subject and template&quot;">​</a></h4><p>The <strong>Subject</strong> line (used only for email-based protocols) and the <strong>Template</strong> body both support alert variables and Velocity replacement syntax. You can also reference any Global Map or Configuration Map entry.</p><h2 id="alert-variables" tabindex="-1">Alert variables <a class="header-anchor" href="#alert-variables" aria-label="Permalink to &quot;Alert variables&quot;">​</a></h2><p>These variables can be used in the Subject and Template fields:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${alertId}</code></td><td>The alert&#39;s unique ID</td></tr><tr><td><code>${alertName}</code></td><td>The alert&#39;s name</td></tr><tr><td><code>${serverId}</code></td><td>The server&#39;s unique ID</td></tr><tr><td><code>${serverName}</code></td><td>The configured server name. Useful for telling instances apart when several report into the same inbox (added in 4.6.0)</td></tr><tr><td><code>${date}</code></td><td>A Velocity DateTool object. Use <code>${date.get(&#39;yyyy-MM-dd HH:mm:ss&#39;)}</code> for formatted output</td></tr><tr><td><code>${systemTime}</code></td><td>The time the error occurred, as a Unix epoch value in milliseconds</td></tr><tr><td><code>${error}</code></td><td>The full error output including error type, source line, message, and stack trace</td></tr><tr><td><code>${errorMessage}</code></td><td>The exception message string, or &quot;No exception message.&quot; if no exception is present</td></tr><tr><td><code>${errorType}</code></td><td>The error category (matches the categories listed above)</td></tr><tr><td><code>${channelId}</code></td><td>The ID of the channel where the error occurred</td></tr><tr><td><code>${channelName}</code></td><td>The name of that channel</td></tr><tr><td><code>${connectorName}</code></td><td>The name of the connector where the error occurred</td></tr><tr><td><code>${connectorType}</code></td><td>The connector protocol name (e.g. &quot;TCP Sender&quot;, &quot;HTTP Listener&quot;), if available</td></tr><tr><td><code>${messageId}</code></td><td>The message ID associated with the error (only present when a message is involved)</td></tr></tbody></table><p>Global Map and Configuration Map entries are also available by name. For example, <code>${myGlobalVar}</code> will resolve if a matching entry exists.</p><h3 id="example-template" tabindex="-1">Example template <a class="header-anchor" href="#example-template" aria-label="Permalink to &quot;Example template&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Channel: ${channelName} (${channelId})</span></span>\n<span class="line"><span>Connector: ${connectorName}</span></span>\n<span class="line"><span>Message ID: ${messageId}</span></span>\n<span class="line"><span>Date: ${date}</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>${error}</span></span></code></pre></div><h2 id="email-configuration" tabindex="-1">Email configuration <a class="header-anchor" href="#email-configuration" aria-label="Permalink to &quot;Email configuration&quot;">​</a></h2><p>For email-based alert actions to work, you need to configure the SMTP settings on the <strong>Server</strong> tab under <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>SMTP Host</strong></td><td>Your mail server hostname</td></tr><tr><td><strong>SMTP Port</strong></td><td>The mail server port</td></tr><tr><td><strong>Send Timeout</strong></td><td>How long to wait before giving up on a connection (in milliseconds)</td></tr><tr><td><strong>Default From Address</strong></td><td>The sender address for outgoing alert emails</td></tr><tr><td><strong>Secure Connection</strong></td><td>None, STARTTLS, or SSL</td></tr><tr><td><strong>Require Authentication</strong></td><td>Whether the mail server requires a username and password</td></tr><tr><td><strong>Username / Password</strong></td><td>SMTP credentials (when authentication is enabled)</td></tr></tbody></table><p>You can test the configuration with the <strong>Send Test Email</strong> button.</p><h2 id="managing-alerts" tabindex="-1">Managing alerts <a class="header-anchor" href="#managing-alerts" aria-label="Permalink to &quot;Managing alerts&quot;">​</a></h2><h3 id="alert-tasks" tabindex="-1">Alert tasks <a class="header-anchor" href="#alert-tasks" aria-label="Permalink to &quot;Alert tasks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Reload the alerts table</td></tr><tr><td><strong>New Alert</strong></td><td>Create a new alert and open the editor</td></tr><tr><td><strong>Import Alert</strong></td><td>Load an alert from an XML file</td></tr><tr><td><strong>Export All Alerts</strong></td><td>Save all alerts as individual XML files</td></tr><tr><td><strong>Export Alert</strong></td><td>Save the selected alert as an XML file</td></tr><tr><td><strong>Delete Alert</strong></td><td>Permanently remove the selected alert</td></tr><tr><td><strong>Edit Alert</strong></td><td>Open the selected alert in the editor</td></tr><tr><td><strong>Enable Alert</strong></td><td>Activate the alert so it begins monitoring</td></tr><tr><td><strong>Disable Alert</strong></td><td>Deactivate the alert without deleting it</td></tr></tbody></table><h3 id="edit-alert-tasks" tabindex="-1">Edit alert tasks <a class="header-anchor" href="#edit-alert-tasks" aria-label="Permalink to &quot;Edit alert tasks&quot;">​</a></h3><p>While editing an alert, two additional tasks are available:</p><ul><li><strong>Save Alert</strong>. Commits your changes. If the alert is enabled, it immediately begins watching for matching errors.</li><li><strong>Export Alert</strong>. Saves the current alert to an XML file.</li></ul>',38)]))}const u=e(o,[["render",s]]);export{p as __pageData,u as default};
